insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values (E'31198a73-b97b-5e40-9bcc-545779cc2ea4',E'Medidas de conservación y resguardo de la Información de Interés Nacional',E'MCR-IIN',null,null,true,ARRAY[E'SNIEG',E'INEGI',E'Información de Interés Nacional',E'Acervo IIN',E'Conservación',E'Resguardo']::text[],E'https://www.snieg.mx/Documentos/Normatividad/Vigente/Medidas_conservacion_y_resguardo_delaIIN.pdf',E'manual') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'abcfd283-1e36-50ff-af31-5995fc49d310',E'Presentación · pág. 2',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Presentación\nEl objetivo de las Medidas de conservación y resguardo de la\nInformación de Interés Nacional (IIN) es el de establecer las medidas\ntécnicas para la seguridad de la Información de Interés Nacional\nque se encuentra en los repositorios a cargo de las Unidades del\nEstado (UE), incluido el Instituto Nacional de Estadística y Geografía\n(INEGI).\nPor lo tanto, son de observancia general para las UE, incluyendo al\nINEGI y sus unidades administrativas que producen o integran IIN.\nEl presente documento está sujeto a revisión por parte del INEGI y\ncualquier actualización será publicada en el Portal del SNIEG.\nAsimismo, es complementario de los siguientes documentos\nnormativos:\n    Esquema de entrega-recepción de la Información de Interés\n    Nacional.\n    Criterios y estándares técnicos y conceptuales para la\n    conservación y resguardo de la Información de Interés\n    Nacional.</pre></div></section>',E'anexo',1,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Medidas de conservación y resguardo',E'Presentación',E'31198a73-b97b-5e40-9bcc-545779cc2ea4') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'35e2d8e7-96cb-5999-af1a-8db6266fe779',E'Marco legal, medidas generales y conservación · pág. 4',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">1. Marco legal\n La Información de Interés Nacional es la señalada en el artículo 59 de la Ley del Sistema\n Nacional de Información Estadística y Geográfica (Ley del SNIEG), así como aquella que la\n Junta de Gobierno determina como tal de acuerdo con el artículo 77 fracción II y 78 de\n dicha Ley.\n El INEGI deberá conservar la IIN que elaboren el propio Instituto y las UE, en términos de lo\n dispuesto en la Ley del SNIEG y en las disposiciones de carácter específico que al efecto\n emita el propio Instituto. Éste, de acuerdo con la misma Ley, deberá conservar también la\n IIN generada por UE que desaparezcan o se desincorporen.\n Por su parte, las Unidades del Estado, cuando desarrollen actividades relacionadas con la\n producción, integración, conservación y difusión de IIN, deberán resguardar y conservar la\n Información, así como su documentación, en la forma y términos que señale el Instituto.\n A fin de normar y coordinar a las Unidades del Estado para la conformación del Acervo de\n IIN, y en lo particular en la conservación y resguardo de la misma, el Instituto emite las\n siguientes medidas.\n2. Medidas generales\n    2.1  Es responsabilidad de las UE en materia de conservación y resguardo, asegurar la\n         integridad, disponibilidad y confidencialidad de los datos y la documentación de\n         la IIN que producen, respecto a daños físicos, pérdida, alteraciones, acceso o\n         difusión no autorizados.\n    2.2  Es obligación de la UE atender las medidas de conservación y resguardo\n         contenidas en este documento, así como la aplicación de la seguridad que se\n         considere necesaria, de conformidad con las mejores prácticas o estándares en la\n         materia, para salvaguardar y proteger la IIN.\n    2.3  La conservación y resguardo de IIN se debe realizar tanto en el Nodo Central como\n         en los Nodos de las UE, mediante procesos de almacenamiento, mantenimiento y\n         gestión para su disponibilidad permanente.\n3. Sobre la conservación y el resguardo de la IIN\n    3.1  La conservación y el resguardo deben mantener la integridad, disponibilidad y\n         confidencialidad, por lo que la IIN debe acompañarse con metadatos:\n               a.  Estructurales, que se refieren a su organización, los elementos que la\n                   integran y los catálogos utilizados, para su correcta interpretación.\n               b.  De referencia, que ayuden a entender el proyecto que dio origen a las\n                   IIN.\n               c.  Administrativos,  incluyendo   datos  técnicos   sobre   la  creación,\n                   almacenamiento, control de acceso y calidad, gestión de recursos y\n                   derechos, condiciones de preservación, mantenimiento, entrega y\n                   migración, entre otros.\n    3.2  Como parte de las medidas de conservación y resguardo de la IIN, los\n         Responsables de la IIN en coordinación con los Responsables Informáticos de cada\n         Nodo, incluido el Nodo Central, deberán atender lo siguiente:</pre></div></section>',E'anexo',2,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Medidas de conservación y resguardo',E'Marco legal, medidas generales y conservación',E'31198a73-b97b-5e40-9bcc-545779cc2ea4') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'0f14dc97-92a5-5569-8147-a0a5d15f8719',E'Seguridad humana, física y ambiental · pág. 5',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">               a.  Proveer los servicios tecnológicos necesarios para la conservación y\n                   resguardo de la IIN.\n               b.  Verificar que los contenidos cumplen con los criterios y estándares\n                   definidos en el documento Criterios y estándares técnicos y\n                   conceptuales para la conservación y resguardo de la IIN.\n               c.  Preparar la Información y su documentación para su integración al\n                   proceso descrito en el documento de Esquema de entrega-recepción\n                   de la IIN.\n               d.  Implementar un mecanismo para el control de cambios que asegure la\n                   integridad y la correcta actualización de las instancias de la IIN.\n               e.  Implementar un control de acceso a la Información con su respectivo\n                   monitoreo.\n               f.  Implementar mecanismos para contar con una copia de la IIN y su\n                   documentación en un lugar físico separado.\n4. Seguridad de la Información\n Se entiende por Seguridad de la Información al conjunto de medidas, funciones, procesos\n y  procedimientos    que,   de   manera    coordinada,   contribuyen   a   preservar  la\n confidencialidad, integridad y disponibilidad de la Información.\n Como parte de las medidas para la conservación y resguardo de la IIN, las UE deberán\n tomar en cuenta los siguientes factores:\n    4.1  Seguridad en el factor humano\n            4.1.1 Las UE implementarán acciones para que sus servidores públicos, así como\n                  el personal externo que por motivo de las funciones que desarrolle esté en\n                  contacto con el Nodo que contiene la IIN, sean orientados en las\n                  funciones que deben desempeñar y en el adecuado uso de la\n                  Información.\n            4.1.2 Las UE promoverán el uso de mecanismos para que cualquier cambio de\n                  adscripción que implique la reasignación de funciones a cargo de sus\n                  servidores públicos, con acceso al Nodo que contiene la IIN que\n                  producen, se realice de forma ordenada y controlada, de manera que\n                  no sustraigan información relacionada con su encargo anterior.\n            4.1.3 Implementar medidas para vigilar que los servidores públicos de las UE que\n                  por motivo de sus funciones tengan acceso al Nodo que contiene la IIN,\n                  no conserven en su poder o sustraigan información confidencial relativa\n                  a la IIN que producen, cuando concluyan su relación laboral.\n    4.2  Seguridad física y ambiental\n            4.2.1 Las UE establecerán acciones que permitan el adecuado suministro de\n                  energía eléctrica y las condiciones medioambientales necesarias para la\n                  operación de los recursos informáticos y el almacenamiento de la\n                  información. Además, deberán contar con la documentación del diseño</pre></div></section>',E'anexo',3,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Medidas de conservación y resguardo',E'Seguridad humana, física y ambiental',E'31198a73-b97b-5e40-9bcc-545779cc2ea4') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'a88bd925-81c6-50a6-8e7a-37c07913a81b',E'Comunicaciones, operaciones y sistemas · pág. 6',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">              de las instalaciones y de los componentes tecnológicos de que disponen,\n              con el fin de poder realizar una adecuada planeación e implantación de\n              controles para la Seguridad de la IIN.\n        4.2.2 Las UE deben prever los mecanismos que generen las condiciones\n              medioambientales     y   definir  los  medios   adecuados     para    el\n              almacenamiento de documentos, considerando el aprovechamiento,\n              optimización del mobiliario y espacios asignados para tal fin.\n        4.2.3 Las UE establecerán acciones para una adecuada implantación de los\n              mecanismos de seguridad y control de acceso físico donde esté ubicado\n              su Nodo. Asimismo, deberán identificar las oficinas y áreas consideradas\n              como de acceso restringido y aplicar las medidas pertinentes para ello.\n4.3   Seguridad de comunicaciones y operaciones; acceso lógico y sistemas de\n      información\n        4.3.1 En lo referente a la seguridad de las comunicaciones y operaciones, el\n              control de accesos lógicos y la adquisición, desarrollo, uso y\n              mantenimiento de los sistemas de información, las UE deberán considerar\n              los siguientes aspectos:\n              a. Que la planeación, adquisición, desarrollo y aceptación de soluciones\n                 tecnológicas (sistema o aplicativos y sus componentes), asignación de\n                 responsabilidades y cambios en la tecnología aseguren la continuidad\n                 de las operaciones, la seguridad de los activos de TIC, la\n                 confidencialidad, integridad y disponibilidad de la información y la\n                 documentación de los procesos, y\n              b. Que los mecanismos para el monitoreo, acceso, respaldo y protección\n                 de la información, así como de la plataforma tecnológica, aseguren la\n                 confidencialidad, integridad y disponibilidad de la información.\n         4.3.2 El Responsable Informático de las UE y del Instituto deberán:\n              a. Verificar que todos los equipos de cómputo de escritorio y portátiles\n                 que formen parte de sus Nodos o tengan acceso a ellos, cumplan con\n                 las siguientes medidas: registro de nombre del equipo, su ubicación y\n                 su responsable; integración a un dominio; tener instalado software de\n                 antivirus; contar con la última versión y parche del sistema operativo\n                 liberado por el proveedor.\n              b. Definir e instrumentar un mecanismo de seguridad para evitar\n                 intrusiones a la infraestructura de los Nodos, incluyendo ataques\n                 externos e internos.\n              c. Realizar respaldos útiles de la IIN para su conservación y resguardo,\n                 cada vez que se actualice o modifique la misma, o en su defecto una\n                 vez al año como mínimo. El Responsable Informático deberá llevar\n                 registro del estado de cada copia y su ubicación.\n              d. En caso de actualización de la IIN, entregará copia al Instituto\n                 conforme al documento: Esquema de entrega-recepción de la IIN,\n                 emitido por el instituto.</pre></div></section>',E'anexo',4,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Medidas de conservación y resguardo',E'Comunicaciones, operaciones y sistemas',E'31198a73-b97b-5e40-9bcc-545779cc2ea4') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'c7096589-ffcc-5532-ae18-79086d295298',E'Respaldos, continuidad y control de acceso · pág. 7',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">              e. Adicionalmente deberá entregar copia de la IIN que producen a\n                 solicitud del Coordinador del Acervo.\n              f. Mantener la vigencia de los formatos de la IIN que produce su UE y de\n                 los medios que la contengan. En caso de que el software utilizado para\n                 manejar sus archivos, tenga actualizaciones deberá verificar la\n                 compatibilidad con los formatos en los que se encuentra su\n                 información y en caso de no ser compatible deberá actualizar sus\n                 formatos. En tanto no se concluya la actualización de todos sus\n                 formatos deberá asegurarse de cumplir con la siguiente medida.\n              g. Mantener una copia del software, soluciones tecnológicas, aplicativos,\n                 parámetros de configuración de los sistemas, estructuras de datos y\n                 datos, que aseguren la conservación y resguardo de la IIN que\n                 producen y su recuperación en caso necesario.\n              h. Establecer medidas de reemplazo de los medios de almacenamiento\n                 de la IIN que produce, con base en la vida útil de éstos, asegurando la\n                 destrucción de los medios desechados que contengan información\n                 confidencial o reservada.\n        4.3.3 Los Responsables Informáticos de las UE y del Nodo Central deberán:\n              a. Documentar los procedimientos de respaldo de la IIN y llevar un registro\n                 de las operaciones de respaldo y recuperación realizadas.\n              b. Realizar en conjunto con los Responsables de la IIN un análisis de\n                 riesgos, a fin de definir los requerimientos de seguridad e identificar los\n                 controles apropiados para procurar la continuidad de los servicios\n                 relacionados con los Nodos.\n              c. Llevar el registro de los incidentes que hayan afectado la Seguridad de\n                 la Información, identificando la causa, qué lo originó, el nivel de\n                 gravedad, los alcances, los efectos percibidos, la solución adoptada y\n                 las medidas establecidas para minimizar la posibilidad de que vuelva\n                 a presentarse.\n              d. Controlar que los cambios en los componentes tecnológicos y de\n                 comunicaciones no afecten a la seguridad de los mismos ni de la\n                 información a la que dan soporte.\n              e. Monitorear necesidades de capacidad de los sistemas en operación y\n                 proyectar las futuras demandas, a fin de procurar el procesamiento y\n                 almacenamiento adecuados tomando en cuenta los nuevos\n                 requerimientos de los sistemas, así como las tendencias proyectadas\n                 para el período estimado de vida útil de cada componente.\n4.4   Control de acceso\n        4.4.1 El Coordinador del Acervo es responsable de:\n              a. Integrar y mantener un directorio de usuarios y administradores en el\n                 que se registrarán los datos de identificación y la vigencia de las\n                 cuentas, verificando periódicamente si se han efectuado cambios y\n                 en caso necesario solicitar la baja de las cuentas.</pre></div></section>',E'anexo',5,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Medidas de conservación y resguardo',E'Respaldos, continuidad y control de acceso',E'31198a73-b97b-5e40-9bcc-545779cc2ea4') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'086add17-87d9-57de-b319-fca48a3b57d9',E'Control de acceso · continuación · pág. 8',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">      b. Definir las atribuciones de cada perfil de acceso al Acervo de IIN.\n4.4.2 Los Responsables Informáticos de las UE y del Nodo Central, deberán:\n      a. Implementar un mecanismo de control de acceso de acuerdo al perfil\n         de cada usuario, que incluya el uso de contraseñas robustas, el registro\n         y rastreabilidad de los usuarios, bloqueo de acceso, el restablecimiento\n         y recuperación de contraseñas.\n      b. Verificar que las atribuciones de cada usuario correspondan al perfil\n         otorgado.\n      c. Eliminar las cuenta de usuario a solicitud de los responsables de la\n         Información.</pre></div></section>',E'anexo',6,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Medidas de conservación y resguardo',E'Control de acceso · continuación',E'31198a73-b97b-5e40-9bcc-545779cc2ea4') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'40a7a0bd-06ba-5e66-b1c1-e2a03227c2be',E'Glosario · primera parte · pág. 9',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Glosario\n                      Conjunto de Información de Interés Nacional que ya ha sido difundida por\n           Acervo de\n                      el Servicio Público de Información, así como sus metadatos, metodologías\n        Información o\n                      y/o especificaciones concretas de la aplicación de las metodologías\n              Acervo\n                      utilizadas en su generación.\n                      Los programas de cómputo, bienes informáticos, soluciones tecnológicas,\n        Activo de TIC  sistemas o aplicativos y sus componentes, las bases de datos o archivos\n                      electrónicos.\n                      Atributo de Seguridad de la Información que indica que la información sólo\n     Confidencialidad\n                      es revelada a individuos autorizados\n      Coordinador del\n            Acervo o  El Director General de Coordinación del SNIEG.\n         Coordinador\n                      Es aquélla que se encuentre identificada, estructurada y almacenada en los\n                      medios y formatos que establezca el Instituto para el respaldo de la\n            Copia útil  Información de Interés Nacional de las Unidades del Estado que formará\n                      parte del Acervo, a la cual se puede acceder directamente para su\n                      consulta y/o procesamiento utilizando los medios electrónicos existentes, sin\n                      que haya afectaciones a la integridad de sus contenidos.\n                      Conjunto de procedimientos y medidas para asegurar la preservación de\n     Conservación de\n                      datos del Acervo y prevenir la ocurrencia de alteraciones físicas en sus\n        la Información\n                      medios de almacenamiento.\n                      Atributo de Seguridad de la Información que consiste en que la\n        Disponibilidad\n                      información puede ser accedida por el personal cuando éste lo requiere.\n                      Conjunto de documentos que acompañan a la Información de Interés\n                      Nacional en su conservación y resguardo: metadatos, metodologías y/o\n      Documentación\n                      especificaciones concretas de la aplicación de las metodologías utilizadas\n                      en su elaboración.\n       INEGI o Instituto  Instituto Nacional de Estadística y Geografía.\n                      A la señalada en el artículo 59 de la Ley del Sistema Nacional de\n       Información de\n                      Información Estadística y Geográfica (LSNIEG), así como aquella que la\n      Interés Nacional,\n                      Junta de Gobierno determine como tal, de acuerdo con lo establecido en\n     Información o IIN\n                      los artículos 77 fracción II y 78 de dicha Ley.\n                      Atributo de Seguridad de la Información referente a que la información está\n           Integridad\n                      completa y sin alteraciones.\n                      Descripción estandarizada de las características de un grupo de datos\n           Metadatos\n                      estadísticos o geográficos.\n                       Procedimiento que ordena y articula el conjunto particular de actividades\n         Metodología\n                       necesarias para producir información estadística y/o geográfica.\n                      Sistema informático para facilitar la administración y acceso del repositorio\n        Nodo Central  digital creado por el INEGI en donde se conserva y resguarda el Acervo de\n                      IIN.\n                      Sistema informático para facilitar la administración y acceso del repositorio\n          Nodo de la\n                      digital creado por cada Unidad del Estado en donde se conserva,\n    Unidad del Estado\n                      resguarda y actualiza su Información de Interés Nacional y su\n              o Nodo\n                      documentación.</pre></div></section>',E'anexo',7,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Medidas de conservación y resguardo',E'Glosario · primera parte',E'31198a73-b97b-5e40-9bcc-545779cc2ea4') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'6e0f747a-a484-5b58-b9c8-4267e5c0cb1a',E'Glosario · segunda parte · pág. 10',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">          Red de\n    Resguardo de\n                  Red distribuida a través de la cual cada Unidad de Estado y el propio\n   Información de\n                  Instituto, se apoyarán para vincularse y coordinarse a fin de integrar,\nInterés Nacional o\n                  conservar y resguardar el Acervo de IIN.\n          Red de\n       Resguardo\n      Repositorio  Sistema electrónico de almacenamiento de información.\n                  Protección de la Información y su documentación, que se implementa en\n  Resguardo de la\n                  los Nodos, contra accesos no autorizados, alteraciones, daños físicos,\n     Información\n                  pérdida total o parcial, entre otros.\n     Responsable  Servidor público designado por cada Unidad del Estado generadora de IIN,\n         de la IIN  responsable de la conservación y resguardo de la misma.\n     Responsable  Servidor público designado por el titular de la Dirección General Adjunta de\n      Informático  Informática, que tenga a su cargo la responsabilidad sobre la coordinación\n      del Instituto  y/o administración del servicio informático del Nodo Central.\n     Responsable\n    Informático o  Servidor público designado por cada Unidad del Estado generadora de IIN,\n     Responsable  responsable de otorgar las condiciones informáticas adecuadas para la\n Informático de la  conservación y resguardo de la Información.\n              UE\n       Usuario de\n                  Al personal de las Unidades del Estado, incluido el Instituto que haga uso de\n       sistemas y\n                  bienes, servicios, recursos informáticos o de información electrónica que\n         servicios\n                  participen en la Red de Resguardo para incorporar Información de Interés\ninformáticos de la\n                  Nacional en el Acervo de Información.\nUnidad del Estado\n                  Capacidad de preservar la confidencialidad, Integridad y disponibilidad de\n  Seguridad de la\n                  la Información a partir de la implementación de medidas técnicas y\n     Información\n                  organizativas.\n                  Las áreas administrativas que cuentan con atribuciones para desarrollar\n                  Actividades Estadísticas y Geográficas o que cuentan con registros\n                  administrativos que permitan obtener IIN de:\n                    a) Las dependencias y entidades de la Administración Pública Federal,\n                       incluyendo a las de la Presidencia de la República y de la Procuraduría\n                       General de la República;\n     Unidades del   b) Los Poderes Legislativo y Judicial de la Federación;\n      Estado o UE\n                    c) Las entidades federativas y los municipios;\n                    d) Los organismos constitucionales autónomos, y\n                    e) Los tribunales administrativos federales.\n                  Cuando el Instituto genere Información se considerará como Unidad del\n                  Estado para efectos de la Ley del Sistema Nacional de Información\n                  Estadística y Geográfica.</pre></div></section>',E'anexo',8,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Medidas de conservación y resguardo',E'Glosario · segunda parte',E'31198a73-b97b-5e40-9bcc-545779cc2ea4') on conflict(id) do nothing;
